/**
 * The command palette (`design/components/command.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/dialog'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  Spread,
  agentMember,
  cell,
  derived,
  elementRef,
  focusPlace,
  focusReturnTarget,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Emitted,
  type IconRole,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/command.module.css'
import { CommandPanel, type CommandPanelProps } from './CommandPanel'

export interface CommandItem {
  id: string
  label: string
  icon?: IconRole
  hint?: string
  group?: string
  keywords?: string[]
  disabled?: boolean
  onSelect: () => void
}

/** The command palette: the inputs it takes, by the React member's prop names. */
export interface CommandProps {
  /**
   * `false` for chained palettes, where the query stays after a command runs.
   */
  closeOnSelect?: boolean
  emptyMessage?: string
  /**
   * The dismiss key label beside the search field (default `esc`). Hosts localize it because a
   * key legend is text too.
   */
  escapeHint?: string
  /**
   * `false` when the app filters the items itself, as with async command sources.
   */
  filter?: false | 'contains'
  items: CommandItem[]
  /**
   * The dialog's accessible name; localized hosts replace the default `Command palette`.
   */
  label?: string
  loading?: boolean
  /**
   * The app owns the ⌘K binding, because a global hotkey is app policy, not vocabulary.
   */
  open: boolean
  placeholder?: string
}

/** The command palette. */
@Component({
  selector: 'pm-command',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, Spread, CommandPanel],
  // prettier-ignore
  template: `<ng-template pmPortal>@if (e1()) {<!-- scrim -->
<div
[pmSpread]="e2()"
[pmRef]="scrim"
></div>}
@if (e3()) {<div
[pmSpread]="e4()"
><!-- panel -->
<div
[pmSpread]="e5()"
[pmRef]="panel"
><pm-command-panel
[items]="e6()"
[placeholder]="e7()"
[escapeHint]="e8()"
[filter]="e9()"
[loading]="e10()"
[emptyMessage]="e11()"
(queryChange)="h1($event)"
(command)="h2()"
></pm-command-panel></div></div>}</ng-template>`,
})
export class Command {
  /**
   * `false` for chained palettes, where the query stays after a command runs.
   */
  readonly closeOnSelect = input<
    Exclude<CommandProps['closeOnSelect'], undefined>,
    CommandProps['closeOnSelect']
  >(true, {
    transform: (value: CommandProps['closeOnSelect']) => (value === undefined ? true : value),
  })
  readonly emptyMessage = input<
    Exclude<CommandProps['emptyMessage'], undefined>,
    CommandProps['emptyMessage']
  >('No results', {
    transform: (value: CommandProps['emptyMessage']) =>
      value === undefined ? 'No results' : value,
  })
  /**
   * The dismiss key label beside the search field (default `esc`). Hosts localize it because a
   * key legend is text too.
   */
  readonly escapeHint = input<
    Exclude<CommandProps['escapeHint'], undefined>,
    CommandProps['escapeHint']
  >('esc', {
    transform: (value: CommandProps['escapeHint']) => (value === undefined ? 'esc' : value),
  })
  /**
   * `false` when the app filters the items itself, as with async command sources.
   */
  readonly filter = input<Exclude<CommandProps['filter'], undefined>, CommandProps['filter']>(
    'contains',
    { transform: (value: CommandProps['filter']) => (value === undefined ? 'contains' : value) },
  )
  readonly items = input.required<CommandProps['items']>()
  /**
   * The dialog's accessible name; localized hosts replace the default `Command palette`.
   */
  readonly label = input<Exclude<CommandProps['label'], undefined>, CommandProps['label']>(
    'Command palette',
    {
      transform: (value: CommandProps['label']) =>
        value === undefined ? 'Command palette' : value,
    },
  )
  readonly loading = input<Exclude<CommandProps['loading'], undefined>, CommandProps['loading']>(
    false,
    { transform: (value: CommandProps['loading']) => (value === undefined ? false : value) },
  )
  /**
   * The app owns the ⌘K binding, because a global hotkey is app policy, not vocabulary.
   */
  readonly open = input.required<CommandProps['open']>()
  readonly placeholder = input<
    Exclude<CommandProps['placeholder'], undefined>,
    CommandProps['placeholder']
  >('Type a command…', {
    transform: (value: CommandProps['placeholder']) =>
      value === undefined ? 'Type a command…' : value,
  })
  readonly onOpenChange = output<boolean>({ alias: 'openChange' })
  protected readonly $ = useMember({
    events: ['openChange'],
    props: {
      closeOnSelect: () => this.closeOnSelect(),
      emptyMessage: () => this.emptyMessage(),
      escapeHint: () => this.escapeHint(),
      filter: () => this.filter(),
      items: () => this.items(),
      label: () => this.label(),
      loading: () => this.loading(),
      open: () => this.open(),
      placeholder: () => this.placeholder(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly query = cell(() => '')
  protected readonly returnTo = cell(() => null as ReturnType<typeof focusPlace>)
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly scrim = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open,
          finalFocusEl: () => focusReturnTarget(this.returnTo.value, [this.panel.value]),
          'aria-label': this.$p.label,
          onEscapeKeyDown: (event) => this.query.value !== '' && event.preventDefault(),
          onOpenChange: (details) => {
            this.$.emit(this.onOpenChange, 'onOpenChange', details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly scrimPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.scrim.value,
      'dialog.scrim',
    ),
  )
  protected readonly panelPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.panel.value,
      'command.panel',
      { side: 'bottom', align: 'center' },
    ),
  )
  private release2: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return this.scrimPresent.value()
  }

  protected e2() {
    if (!this.scrimPresent.value()) return undefined as never
    return mergeParts(this.api.value.getBackdropProps(), { class: styles.scrim, hidden: undefined })
  }

  protected e3() {
    return this.panelPresent.value()
  }

  protected e4() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps(), { class: styles.positioner })
  }

  protected e5() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      hidden: undefined,
      'aria-describedby': undefined,
      'data-loading': this.$p.loading ? '' : undefined,
      'data-member': 'command',
    })
  }

  protected e6(): CommandPanelProps['items'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.items
  }

  protected e7(): CommandPanelProps['placeholder'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.placeholder
  }

  protected e8(): CommandPanelProps['escapeHint'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.escapeHint
  }

  protected e9(): CommandPanelProps['filter'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.filter
  }

  protected e10(): CommandPanelProps['loading'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.loading
  }

  protected e11(): CommandPanelProps['emptyMessage'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.emptyMessage
  }

  protected h1($event: Emitted<CommandPanel['onQueryChange']>): void {
    if (!this.panelPresent.value()) return
    this.query.value = $event
  }

  protected h2(): void {
    if (!this.panelPresent.value()) return
    void (this.$p.closeOnSelect && this.api.value.setOpen(false))
  }

  private effect1(): void {
    void (this.api.value.open && (this.returnTo.value = focusPlace(document.activeElement)))
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'Command',
      element: () => this.panel.value,
      state: () => ({
        open: this.api.value.open,
        items: this.$p.items.map((item) => ({
          id: item.id,
          label: item.label,
          ...(item.disabled === true ? { disabled: true } : {}),
        })),
        query: this.api.value.open ? this.query.value : '',
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => (
            this.$p.items.find((item) => item.id === value)?.onSelect(),
            this.api.value.open && this.$p.closeOnSelect && this.api.value.setOpen(false)
          ),
        },
        close: () => this.api.value.open && this.api.value.setOpen(false),
      },
    })
    this.release2 = () => {
      ran()
    }
  }
}
